  h += ".card{background:#161a22;border:1px solid #1f2532;border-radius:14px;padding:14px;margin:10px 0}";
  h += ".btns{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px}";
  h += "button{border:1px solid #242b3a;background:#222837;color:#fff;padding:12px;border-radius:12px;font-weight:600;cursor:pointer}";
