  h += ".tab.active{outline:2px solid #2b8cff;outline-offset:2px} .hidden{display:none}";
  h += "label{display:block;margin-bottom:6px;color:#9aa3b2} input,select{width:100%;padding:8px;border-radius:8px;border:1px solid #202638;background:#111521;color:#fff}";
  h += ".row{display:grid;grid-template-columns:200px 1fr;gap:10px;align-items:center}";
  h += "</style></head><body><div class='wrap'>";
