  h += "<option value='3'>Нагрев</option><option value='4'>Поддержание</option><option value='5'>Остывание</option></select></div>";
  h += "<div class='row'><label>Уставка подачи, °C</label><input id='setp' type='number' min='30' max='85' step='1' value='60'></div>";
  h += "<button id='apply'>Применить</button>";
