  h += "<script>";
  h += "const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));";
  h += "function switchTab(t){ $$('.tab').forEach(x=>x.classList.toggle('active',x.dataset.tab===t)); $('#tab-panel').classList.toggle('hidden',t!=='panel'); $('#tab-settings').classList.toggle('hidden',t!=='settings'); }";
  h += "$$('.tab').forEach(x=>x.addEventListener('click',()=>switchTab(x.dataset.tab)));";
  h += "async function fetchStatus(){ try{ const r=await fetch('/api/status',{cache:'no-store'}); const j=await r.json();";
  h += "$('#t1').textContent=(j.temp&&j.temp.ds1!=null)?Number(j.temp.ds1).toFixed(1):'—';";
  h += "$('#t2').textContent=(j.temp&&j.temp.ds2!=null)?Number(j.temp.ds2).toFixed(1):'—';";
  h += "$('#t3').textContent=(j.temp&&j.temp.stack!=null)?Number(j.temp.stack).toFixed(1):'—';";
  h += "document.querySelectorAll('.btns button').forEach(b=>b.classList.toggle('active', Number(b.dataset.speed)===Number(j.speed||0)));";
  h += "$('#modeName').textContent=(j.boiler&&j.boiler.modeName)||'—'; $('#setp').value=(j.boiler&&j.boiler.setpoint)||60; }catch(e){} }";
  h += "async function sendSpeed(s){ try{ const r=await fetch('/api/cmd',{method:'POST',headers:{'Content-Type':'application/json; charset=utf-8'},body:JSON.stringify({speed:Number(s)})}); const j=await r.json(); }catch(e){ alert('ERR: '+e.message);} }";
  h += "async function applyMode(){ try{ const body={mode:Number($('#boilMode').value), setpoint:Number($('#setp').value)}; await fetch('/api/boiler',{method:'POST',headers:{'Content-Type':'application/json; charset=utf-8'},body:JSON.stringify(body)}); await fetchStatus(); }catch(e){alert('Ошибка: '+e.message);} }";
  h += "document.querySelectorAll('.btns button').forEach(b=>b.addEventListener('click',()=>sendSpeed(b.dataset.speed)));";
