  h += "$('#btnReloadLogs').addEventListener('click', async()=>{ try{ const r=await fetch('/api/logs',{cache:'no-store'}); $('#logs').textContent=await r.text(); }catch(e){ $('#logs').textContent='Ошибка: '+e.message; } });";
