  h += "for(let i=0;i<4;i++){ $('#c_s'+i).value=c.steps[i]; $('#c_ton'+i).value=c.ton[i]; }";
  h += "$('#c_off_min').value=c.off_min; $('#c_off_max').value=c.off_max; $('#c_off_base').value=c.off_base; $('#c_alpha').value=c.alpha;";
  h += "$('#c_ramp').value=c.ramp_sec; $('#c_rsafe').value=c.ramp_safety; $('#c_ign').value=c.ign_ms; $('#c_cool').value=c.cool_ms; }";
  h += "async function cfgSave(){ const m=mVal(); const c={ T_set:Number($('#c_T_set').value), T_hyst:Number($('#c_T_hyst').value), Kp:Number($('#c_Kp').value), Ki:Number($('#c_Ki').value), Tflue_low:Number($('#c_Tfl_low').value), Tflue_high:Number($('#c_Tfl_high').value), steps:[Number($('#c_s0').value),Number($('#c_s1').value),Number($('#c_s2').value),Number($('#c_s3').value)], ton:[Number($('#c_ton0').value),Number($('#c_ton1').value),Number($('#c_ton2').value),Number($('#c_ton3').value)], off_min:Number($('#c_off_min').value), off_max:Number($('#c_off_max').value), off_base:Number($('#c_off_base').value), alpha:Number($('#c_alpha').value), ramp_sec:Number($('#c_ramp').value), ramp_safety:Number($('#c_rsafe').value), ign_ms:Number($('#c_ign').value), cool_ms:Number($('#c_cool').value)}; await fetch('/api/profile?m='+m,{method:'POST',headers:{'Content-Type':'application/json; charset=utf-8'},body:JSON.stringify(c)}); alert('Профиль сохранён'); }";
  h += "async function cfgApplyToCurrent(){ const m=mVal(); await fetch('/api/boiler',{method:'POST',headers:{'Content-Type':'application/json; charset=utf-8'},body:JSON.stringify({mode:m})}); await fetchStatus(); alert('Профиль применён'); }";
  h += "$('#cfgLoad').addEventListener('click', cfgLoad); $('#cfgSave').addEventListener('click', cfgSave); $('#cfgApplyToCurrent').addEventListener('click', cfgApplyToCurrent); $('#cfgMode').addEventListener('change', cfgLoad);";
  h += "fetchStatus(); setInterval(fetchStatus,1000); cfgLoad();";
  h += "</script></div></body></html>";
  return h;
